constraints:
1 <= n <= 10^{4}
1 <= arr[i] <= 10^{4}

expected time complexity: O(n)
expected auxiliary space: O(n)

standard_solution_code:
class Solution:

	def print_next_greater_freq(self, arr, n):
		stack = []
		res = [-1] * n
		freq = {}
		for i in arr:
			if i not in freq:
				freq[i] = 1
			else:
				freq[i] += 1
		for i in range(n):
			while stack and freq[arr[stack[-1]]] < freq[arr[i]]:
				res[stack.pop()] = arr[i]
			stack.append(i)
		return res
